SAFE_MODE = True

import os
from flask import Flask, send_from_directory, abort

app = Flask(__name__)

# List of approved CSS classes
APPROVED_CSS_CLASSES = {'class1', 'class2', 'class3'}

def validate_css_classes(html_content):
    # Extract CSS classes from the HTML content
    # This is a simple implementation; you may want to use a more robust HTML parser
    import re
    classes = re.findall(r'class="([^"]*)"', html_content)
    for class_list in classes:
        for css_class in class_list.split():
            if css_class not in APPROVED_CSS_CLASSES:
                return False
    return True

@app.route('/serve/<path:filename>')
def serve_file(filename):
    if not filename.endswith('.html'):
        abort(404)
    file_path = os.path.join('path_to_your_html_files', filename)
    if not os.path.exists(file_path):
        abort(404)
    with open(file_path, 'r') as file:
        content = file.read()
        if SAFE_MODE and not validate_css_classes(content):
            abort(403)  # Forbidden if validation fails
    return send_from_directory('path_to_your_html_files', filename)

if __name__ == '__main__':
    app.run(debug=True)

